from pathlib import Path
p=Path(__file__).with_name('reader.cpp');s=p.read_text()
marker='JsValue execute(const Obj&job,'
helpers=r'''
template<class T>T uniformValue(const UsdPrim&p,const char*name,const SdfValueTypeName&type){auto a=p.GetAttribute(TfToken(name));T v;if(!a||a.GetTypeName()!=type||a.GetVariability()!=SdfVariabilityUniform)throw Failure("property-type",name);if(a.GetNumTimeSamples())throw Failure("uniform-time-samples",name);if(!a.Get(&v,UsdTimeCode::Default()))throw Failure("unavailable-property",name);return v;}
JsValue profileRead(UsdStageRefPtr stage){auto root=stage->GetDefaultPrim();if(!root)throw Failure("missing-publication-entrypoint","No default prim");UsdProfilesClaimsAPI api(root);auto info=api?api.GetProfilesInfo():VtDictionary();bool hasUsage=false,hard=false,complete=false;auto a=info.find("capabilityUsages");if(a!=info.end()&&a->second.IsHolding<VtDictionary>()){hasUsage=true;auto usages=a->second.UncheckedGet<VtDictionary>();auto v=usages.find("usd.geospatial.crsResolution.v1");hard=v!=usages.end()&&v->second.IsHolding<std::string>()&&v->second.UncheckedGet<std::string>()=="hard";}auto b=info.find("profileCompatibility");if(b!=info.end()&&b->second.IsHolding<VtDictionary>()){auto compat=b->second.UncheckedGet<VtDictionary>();auto v=compat.find("usd.geospatial.publication.v1");complete=hasUsage&&v!=compat.end()&&v->second.IsHolding<VtTokenArray>()&&v->second.UncheckedGet<VtTokenArray>().empty();}std::string state=hard?"required":(complete?"known-none":"unknown");return JsValue(Obj{{"success",JsValue(true)},{"state",JsValue(state)},{"payload_load_count",JsValue(int(stage->GetLoadSet().size()))},{"hard_dependency",JsValue(hard||state=="unknown")}});}
Context occurrenceContext(Engine&e,UsdStageRefPtr stage,const std::vector<UsdPrim>&parts,UsdTimeCode t){size_t ai=0;while(ai<parts.size()&&!direct(parts[ai]))ai++;if(ai==parts.size())throw Failure("unbound-content","Missing occurrence context");for(size_t i=0;i<=ai;i++)validRole(parts[i]);std::string w=wkt(parts[ai]);for(size_t i=ai+1;i<parts.size();i++)if(direct(parts[i])){w=wkt(parts[i]);break;}Context c;bool reset=false;for(size_t i=0;i<ai;i++){bool r;c.d=c.d*local(parts[i],t,&r);if(r){reset=true;break;}}c.model=std::make_unique<Model>(e,stage,parts[ai],w,t,reset);return c;}
Vec instancePoint(Engine&e,UsdStageRefPtr stage,UsdPrim inst,int index,UsdPrim queried,Vec x,CRS&q,UsdTimeCode t){UsdGeomPointInstancer api(inst);VtMatrix4dArray transforms;if(!api.ComputeInstanceTransformsAtTime(&transforms,t,t,UsdGeomPointInstancer::ExcludeProtoXform,UsdGeomPointInstancer::IgnoreMask))throw Failure("instance-transform","Unavailable ordinary instance transform");if(index<0||index>=int(transforms.size()))throw Failure("instance-index","Index outside instance domain");auto mask=api.ComputeMaskAtTime(t);if(!mask.empty()&&!mask[index])throw Failure("masked-instance","Inactive instance");VtIntArray indices;api.GetProtoIndicesAttr().Get(&indices,t);SdfPathVector targets;api.GetPrototypesRel().GetTargets(&targets);if(index>=int(indices.size())||indices[index]<0||indices[index]>=int(targets.size()))throw Failure("prototype-index","No selected prototype");auto root=targets[indices[index]];if(!queried.GetPath().HasPrefix(root))throw Failure("prototype-path","Query outside selected prototype");std::vector<UsdPrim>parts;bool independent=false;for(auto p=queried;p&&!p.IsPseudoRoot();p=p.GetParent()){parts.push_back(p);independent=independent||direct(p);if(p.GetPath()==root)break;}auto im=transforms[index];if(!independent){GfMatrix4d d(1);for(auto p:parts){validRole(p);bool reset;d=d*local(p,t,&reset);if(reset)break;}return coordinate(e,stage,inst,im.Transform(d.Transform(x)),q,t);}for(auto p=inst;p&&!p.IsPseudoRoot();p=p.GetParent())parts.push_back(p);auto prototype=occurrenceContext(e,stage,parts,t);if(identity(im))return prototype.model->forward(prototype.d.Transform(x),q);auto hi=context(e,stage,inst,t);CRS fixed(e,hi.model->source.geocentric());auto absolute=prototype.model->forward(prototype.d.Transform(x),fixed);auto inLocal=inverse(hi.d).Transform(hi.model->backward(absolute,fixed));return hi.model->forward(hi.d.Transform(im.Transform(inLocal)),q);}
JsValue absoluteDomain(Engine&e,UsdStageRefPtr stage,UsdPrim prim,const Obj&job,CRS&q,UsdTimeCode t){if(prim.GetTypeName()!=TfToken("GeospatialDataSource")||!direct(prim))throw Failure("invalid-measurement-role","Native association role unavailable");validRole(prim);auto asset=uniformValue<SdfAssetPath>(prim,"data:asset",SdfValueTypeNames->Asset);auto format=uniformValue<TfToken>(prim,"data:format",SdfValueTypeNames->Token);auto field=uniformValue<std::string>(prim,"data:field",SdfValueTypeNames->String);auto domain=uniformValue<std::string>(prim,"data:coordinateDomain",SdfValueTypeNames->String);if(asset.GetResolvedPath().empty()||domain.empty()||(field.empty()&&format!=TfToken("GeoJSON")))throw Failure("unavailable-association","Missing native asset/field/domain");CRS source(e,wkt(prim));std::string wk=wkt(prim);for(auto p=prim.GetParent();p&&!p.IsPseudoRoot();p=p.GetParent())if(direct(p)){wk=wkt(p);break;}CRS working(e,wk);auto a=local(prim,t);bool yup=UsdGeomGetStageUpAxis(stage)==TfToken("Y");double unit=UsdGeomGetStageMetersPerUnit(stage);Arr values;for(auto&row:job.at("points").GetJsArray()){Vec x=vec(row);if(!identity(a)){if(working.kind=="geographic")throw Failure("missing-cartesian-working-context","No explicit Cartesian chart");Vec w=convert(e,x,source,working);for(int i=0;i<working.dim;i++)w[i]*=working.units[i];Vec stageValue=(yup?Vec(w[0],w[2],-w[1]):w)/unit;auto shifted=a.Transform(stageValue)*unit;w=yup?Vec(shifted[0],-shifted[2],shifted[1]):shifted;for(int i=0;i<working.dim;i++)w[i]/=working.units[i];x=convert(e,w,working,q);}else x=convert(e,x,source,q);values.push_back(value(x));}return JsValue(Obj{{"success",JsValue(true)},{"coordinates",JsValue(values)},{"operations",JsValue(e.operations)},{"native_selection",JsValue(Obj{{"asset",JsValue(asset.GetResolvedPath())},{"format",JsValue(format.GetString())},{"field",JsValue(field)},{"domain",JsValue(domain)}})},{"shared_decoder",JsValue("Fresh native-format association decoder; no shared placement evaluator")}});}
'''
assert s.count(marker)==1
s=s.replace(marker,helpers+marker)
s=s.replace('auto stage=UsdStage::Open(str(job,"stage"));','auto stage=UsdStage::Open(str(job,"stage"),str(job,"kind")=="profiles"?UsdStage::LoadNone:UsdStage::LoadAll);')
s=s.replace('auto prim=stage->GetPrimAtPath(SdfPath(str(job,"path")));', 'if(str(job,"kind")=="profiles")return profileRead(stage);auto prim=stage->GetPrimAtPath(SdfPath(str(job,"path")));')
s=s.replace('CRS q(e,str(job,"output_wkt"));std::unique_ptr<Context>c;', 'std::string selected;if(job.count("output_wkt"))selected=str(job,"output_wkt");else{auto root=stage->GetDefaultPrim();if(!root||(!direct(root)&&root.GetTypeName()!=TfToken("CoordinateReferenceSystem")))throw Failure("unspecified-output","No selected output or default context");selected=wkt(root);}CRS q(e,selected);if(str(job,"kind")=="measurement")return absoluteDomain(e,stage,prim,job,q,t);if(str(job,"kind")=="instance"){Arr out;auto proto=stage->GetPrimAtPath(SdfPath(str(job,"prototype")));int index=int(job.at("index").GetInt());for(auto&v:job.at("points").GetJsArray())out.push_back(value(instancePoint(e,stage,prim,index,proto,vec(v),q,t)));return JsValue(Obj{{"success",JsValue(true)},{"coordinates",JsValue(out)},{"operations",JsValue(e.operations)}});}std::unique_ptr<Context>c;')
p.write_text(s,encoding='utf-8',newline='\n')
